node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Verify current warranty state
const warranty = db.prepare(\"SELECT * FROM warranties WHERE warranty_id = 'WR-4A95C8'\").get();
console.log('=== CURRENT WARRANTY STATUS ===');
console.log(JSON.stringify(warranty, null, 2));

// Check eligibility
const now = new Date('2026-09-10'); // approximate current date based on order context
const endDate = new Date(warranty.end_date);
console.log('\n=== ELIGIBILITY CHECK ===');
console.log('Status:', warranty.status);
console.log('Claims used:', warranty.claim_count, '/', warranty.max_claims);
console.log('Warranty end date:', warranty.end_date);
console.log('Within warranty period:', now <= endDate);
console.log('Claims remaining:', warranty.max_claims - warranty.claim_count);
console.log('Eligible:', warranty.status === 'active' && warranty.claim_count < warranty.max_claims && now <= endDate);
"

